/* text with numbers, names or places in it */
var PATTERNS = [];
function p(re, fn){ PATTERNS.push([re, fn]); }
var MES = ["ene","feb","mar","abr","may","jun","jul","ago","sept","oct","nov","dic"];
var MON = {jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11};
var MESES = ["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"];
var EXTRA = {
  months:["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"],
  monthsMini:["E","F","M","A","M","J","J","A","S","O","N","D"],
  langName:"Español"
};
var pl = function(n, one, many){ return (+n === 1 ? one : many); };
var poss = function(name){ return name === "Your" ? "Tu" : null; };
/* dates: "21 Oct 2026", "02 MAR", "02 MAR 26" */
p(/^(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) (\d{4})$/i, function(m){ return (+m[1]) + " " + MES[MON[m[2].toLowerCase()]] + " " + m[3]; });
p(/^(\d{1,2}) (JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)(?: (\d{2}))?$/, function(m){ return m[1] + " " + MES[MON[m[2].toLowerCase()]].toUpperCase() + (m[3] ? " " + m[3] : ""); });
p(/^(January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})$/, function(m){ return MESES[MON[m[1].slice(0,3).toLowerCase()]] + " de " + m[2]; });
/* counts */
p(/^(\d+) of (\d+)$/, function(m){ return m[1] + " de " + m[2]; });
p(/^(\d+) of (\d+) countries$/, function(m){ return m[1] + " de " + m[2] + " países"; });
p(/^(\d+) of (\d+) must-trys$/, function(m){ return m[1] + " de " + m[2] + " imprescindibles"; });
p(/^(\d+) of (\d+) must-trys eaten$/, function(m){ return m[1] + " de " + m[2] + " imprescindibles probados"; });
p(/^(\d+)\/(\d+) eaten$/, function(m){ return m[1] + "/" + m[2] + " probados"; });
p(/^None of its (\d+) must-trys yet$/, function(m){ return "Aún ninguno de sus " + m[1] + " imprescindibles"; });
p(/^Stamps: (\d+) of (\d+)$/, function(m){ return "Sellos: " + m[1] + " de " + m[2]; });
p(/^(\d+) (countries|country)$/, function(m){ return m[1] + " " + pl(m[1], "país", "países"); });
p(/^(\d+) ctry$/, function(m){ return m[1] + " " + pl(m[1], "país", "países"); });
p(/^(\d+) (dishes|dish)$/, function(m){ return m[1] + " " + pl(m[1], "plato", "platos"); });
p(/^(\d+) (people|person)$/, function(m){ return m[1] + " " + pl(m[1], "persona", "personas"); });
p(/^(\d+) (meals|meal)$/, function(m){ return m[1] + " " + pl(m[1], "comida", "comidas"); });
p(/^(\d+) (meals|meal) there$/, function(m){ return m[1] + " " + pl(m[1], "comida", "comidas") + " allí"; });
p(/^(\d+) (photos|photo)$/, function(m){ return m[1] + " " + pl(m[1], "foto", "fotos"); });
p(/^(\d+) (likes|like)$/, function(m){ return m[1] + " me gusta"; });
p(/^(\d+) (stamps|stamp)$/, function(m){ return m[1] + " " + pl(m[1], "sello", "sellos"); });
p(/^(\d+) must-trys?$/, function(m){ return m[1] + " " + pl(m[1], "imprescindible", "imprescindibles"); });
p(/^(\d+) (continents|continent)$/, function(m){ return m[1] + " " + pl(m[1], "continente", "continentes"); });
p(/^(\d+) (times|time)$/, function(m){ return m[1] + " " + pl(m[1], "vez", "veces"); });
p(/^tried$/, function(){ return "probados"; });
p(/^from (\d+) (ratings?) in your group$/, function(m){ return "de " + m[1] + " " + pl(m[1], "puntuación", "puntuaciones") + " en tu grupo"; });
p(/^from (\d+) (meals?)$/, function(m){ return "de " + m[1] + " " + pl(m[1], "comida", "comidas"); });
p(/^Rated (\d) out of 5$/, function(m){ return "Puntuado con " + m[1] + " de 5"; });
p(/^(Taste|Presentation|Value for money|Value|Overall): (\d) stars?$/, function(m, t){ return t(m[1]) + ": " + m[2] + " " + pl(m[2], "estrella", "estrellas"); });
p(/^for new must-trys in (\d{4})$/, function(m){ return "por imprescindibles nuevos en " + m[1]; });
p(/^across (\d+) continents?: (.+)$/, function(m, t){ var c = m[2].split(", ").map(t); return "en " + m[1] + " " + pl(m[1], "continente", "continentes") + ": " + (c.length > 1 ? c.slice(0, -1).join(", ") + " y " + c[c.length - 1] : c[0]); });
/* places and names */
p(/^([^·]+) speciality$/, function(m, t){ return "especialidad de " + t(m[1]); });
p(/^Across (.+)$/, function(m, t){ return "En todo " + t(m[1]); });
p(/^No researched city guide for (.+) yet\. Ask Claude in your chat to research a city here and it'll be added with real places and sources\.$/, function(m, t){ return "Aún no hay una guía de ciudad investigada para " + t(m[1]) + ". Pide a Claude en tu chat que investigue una ciudad y se añadirá con sitios y fuentes reales."; });
p(/^Nothing matches "(.*)"\. Try a dish like "ramen" or a country like "Germany"\.$/, function(m){ return "Nada coincide con «" + m[1] + "». Prueba con un plato como «ramen» o un país como «Alemania»."; });
p(/^No countries on the list match "(.*)"$/, function(m){ return "Ningún país de la lista coincide con «" + m[1] + "»"; });
p(/^No country on the map matches "(.*)"$/, function(m){ return "Ningún país del mapa coincide con «" + m[1] + "»"; });
p(/^Photo by (.+)$/, function(m){ return "Foto de " + m[1]; });
p(/^(.+)'s map$/, function(m){ return "Mapa de " + m[1]; });
p(/^(.+)'s stamps$/, function(m){ return "Sellos de " + m[1]; });
p(/^(.+)'s passport$/, function(m){ return "Pasaporte de " + m[1]; });
p(/^Your (\d{4}) so far on a plate$/, function(m){ return "Tu " + m[1] + " en un plato, hasta ahora"; });
p(/^Your (\d{4}) on a plate$/, function(m){ return "Tu " + m[1] + " en un plato"; });
p(/^(.+)'s (\d{4}) so far on a plate$/, function(m){ return "El " + m[2] + " de " + m[1] + " en un plato, hasta ahora"; });
p(/^(.+)'s (\d{4}) on a plate$/, function(m){ return "El " + m[2] + " de " + m[1] + " en un plato"; });
p(/^Your (\d{4})$/, function(m){ return "Tu " + m[1]; });
p(/^(.+)'s (\d{4})$/, function(m){ return "El " + m[2] + " de " + m[1]; });
p(/^Your (\d{4}) food personality$/, function(m){ return "Tu personalidad gastronómica de " + m[1]; });
p(/^(.+)'s (\d{4}) food personality$/, function(m){ return "La personalidad gastronómica de " + m[1] + " en " + m[2]; });
p(/^(.+)'s hungriest month$/, function(m){ return "El mes más hambriento de " + m[1]; });
p(/^Best bite: (.+)$/, function(m, t){ return "Mejor bocado: " + t(m[1]); });
p(/^Remove (.+) from (.+)\?$/, function(m){ return "¿Quitar a " + m[1] + " de " + m[2] + "?"; });
p(/^(.+) is no longer an admin\.$/, function(m){ return m[1] + " ya no es admin."; });
p(/^(.+) is now an admin\.$/, function(m){ return m[1] + " ahora es admin."; });
p(/^Make (.+) an admin\?$/, function(m){ return "¿Hacer admin a " + m[1] + "?"; });
p(/^Leave (.+)\?$/, function(m){ return "¿Salir de " + m[1] + "?"; });
p(/^Delete (.+)\?$/, function(m){ return "¿Eliminar " + m[1] + "?"; });
p(/^Renamed to (.+)\.$/, function(m){ return "Nuevo nombre: " + m[1] + "."; });
p(/^Friends now see you as (.+)\.$/, function(m){ return "Tus amigos ahora te ven como " + m[1] + "."; });
p(/^Added (.+)\.$/, function(m){ return "Añadido: " + m[1] + "."; });
p(/^Removed (.+)\.$/, function(m){ return "Quitado: " + m[1] + "."; });
